recipes.code:
{
  "inputs": [
    {
      "id": "adn-api-key",
      "type": "promptString",
      "description": "AudioDN server-side API key (adn_...). Required for live API tools; knowledge/doc tools work without it.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@audiodn/mcp@0.3.3"
      ],
      "env": {
        "ADN_API_KEY": "${input:adn-api-key}",
        "ADN_API_BASE_URL": "<adn-api-base-url>",
        "ADN_MCP_ALLOW_DELETE": "<adn-mcp-allow-delete>"
      }
    }
  }
}
